var i=[{title:`Objawy alarmowe`,text:`Natychmiast przerwij ćwiczenia, jeśli masz ból lub ucisk w klatce piersiowej, mdlejesz, masz silną duszność bez wyraźnej przyczyny, czujesz nagłe osłabienie po jednej stronie, masz silny nowy ból głowy ze zmianami neurologicznymi lub szybko rozwija się poważna reakcja. Dyskomfort w klatce piersiowej z poceniem się, nudnościami, zawrotami głowy lub bólem promieniującym do ramienia lub szczęki wymaga wezwania służb ratunkowych.`},{title:`Inne poważne sygnały ostrzegawcze`,text:`Nie trenuj przez nagły silny ból stawu lub pleców, wyraźny obrzęk po urazie, niemożność obciążenia kończyny, narastające osłabienie lub nowe drętwienie. Ból pleców razem z utratą kontroli nad pęcherzem lub jelitami albo drętwieniem w okolicy pachwiny wymaga natychmiastowej oceny w trybie nagłym.`},{title:`Co robić`,text:`Przerwij, zabezpiecz miejsce i wezwij pomoc. Zadzwoń pod lokalny numer alarmowy w przypadku objawów alarmowych i nie prowadź samochodu sam, jeśli możesz być poważnie chory lub ranny. Jeśli jesteś partnerem treningowym, nie próbuj ustalać przyczyny i nie zachęcaj osoby do dokończenia serii. TrainUp nie może ocenić stanu nagłego, zdiagnozować choroby ani zastąpić wykwalifikowanego specjalisty.`},{title:`Profilaktyka ma granice`,text:`Rozgrzewki, rozsądne obciążenia i stopniowa progresja mogą zmniejszyć możliwy do uniknięcia stres, ale nie mogą wykluczyć każdego problemu medycznego. Jeśli masz rozpoznaną chorobę serca lub poważne czynniki ryzyka, możesz potrzebować osobistej porady lekarza, zanim zaczniesz intensywne ćwiczenia.`}];var o=[{label:`NHS: ból w klatce piersiowej i objawy alarmowe`,url:`https://www.nhs.uk/symptoms/chest-pain/`},{label:`NHS: ból pleców i pilne sygnały ostrzegawcze`,url:`https://www.nhs.uk/conditions/back-pain/`},{label:`NHS: ból stawów`,url:`https://www.nhs.uk/symptoms/joint-pain/`}];var n={sections:i,sources:o};export{n as default,i as sections,o as sources};